use vstd::prelude::*;

verus! {

fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
    ensures
        // outer length is exactly 1
        result@.len() == 1,
        // the only row has the same length as the input
        result@[0]@.len() == arr@.len(),
        // elementwise equality, order preserved
        forall|i: int|
            0 <= i < arr@.len() ==> result@[0]@[i] == arr@[i],
{
    // Build the single row by copying `arr` element-by-element.
    let mut row: Vec<f32> = Vec::new();
    let mut i: usize = 0;

    while i < arr.len()
        invariant
            i <= arr.len(),
            row@.len() == i as nat,
            forall|j: int| 0 <= j < i as int ==> row@[j] == arr@[j],
        decreases
            arr.len() - i,
    {
        row.push(arr[i]);
        i = i + 1;
    }

    // Wrap it into a 2D vector with exactly one row.
    let mut result: Vec<Vec<f32>> = Vec::new();
    result.push(row);

    // Establish the postconditions about the final structure.
    assert(result@.len() == 1);
    assert(result@[0]@.len() == arr@.len());
    assert(forall|k: int| 0 <= k < arr@.len() ==> result@[0]@[k] == arr@[k]);

    result
}

} // verus!

